<?php
declare(strict_types=1);
namespace Safaricom\Mpesa\Support;
use InvalidArgumentException;
final class Money { public function __construct(public readonly int $minor,public readonly string $currency='KES',public readonly int $scale=2){if($minor<0)throw new InvalidArgumentException('Money cannot be negative.');if(!preg_match('/^[A-Z]{3}$/',$currency))throw new InvalidArgumentException('Currency must be a 3-letter ISO 4217 code.');if($scale<0||$scale>4)throw new InvalidArgumentException('Money scale must be between 0 and 4.');} public static function fromDecimal(string|int|float $amount,string $currency='KES',int $scale=2):self{$normalized=trim((string)$amount);if(!preg_match('/^\d+(?:\.\d+)?$/',$normalized))throw new InvalidArgumentException('Invalid non-negative decimal amount.');[$whole,$fraction]=array_pad(explode('.',$normalized,2),2,'');$fraction=substr(str_pad($fraction,$scale,'0'),0,$scale);$minor=((int)$whole*(10**$scale))+(int)($fraction===''?0:$fraction);return new self($minor,strtoupper($currency),$scale);} public function decimal():string{if($this->scale===0)return(string)$this->minor;$divisor=10**$this->scale;return intdiv($this->minor,$divisor).'.'.str_pad((string)($this->minor%$divisor),$this->scale,'0',STR_PAD_LEFT);} public function darajaAmount():int{return(int)round((float)$this->decimal(),0,PHP_ROUND_HALF_UP);} public function add(self $other):self{$this->assertCompatible($other);return new self($this->minor+$other->minor,$this->currency,$this->scale);} public function subtract(self $other):self{$this->assertCompatible($other);if($other->minor>$this->minor)throw new InvalidArgumentException('Resulting money value would be negative.');return new self($this->minor-$other->minor,$this->currency,$this->scale);} private function assertCompatible(self $other):void{if($this->currency!==$other->currency||$this->scale!==$other->scale)throw new InvalidArgumentException('Money values must use the same currency and scale.');} }
